commands.command:
set -eu
install -d -m 0755 -o nodeapp -g nodeapp /home/nodeapp/app
install -d -m 0755 -o nodeapp -g nodeapp /home/nodeapp/.config/containers/systemd
cat > /home/nodeapp/app/server.js <<'ANTRIEB_SERVER_EOF'
'use strict';

const http = require('node:http');
const body = 'Hello, world!';

const server = http.createServer((request, response) => {
  if (request.method === 'GET' && request.url === '/') {
    response.writeHead(200, {
      'Content-Type': 'text/plain; charset=utf-8',
      'Content-Length': Buffer.byteLength(body)
    });
    response.end(body);
    return;
  }

  response.writeHead(404, { 'Content-Length': '0' });
  response.end();
});

server.listen(8080, '0.0.0.0');
ANTRIEB_SERVER_EOF
cat > /home/nodeapp/app/Containerfile <<'ANTRIEB_CONTAINER_EOF'
FROM docker.io/library/node:22-alpine
WORKDIR /app
COPY --chown=node:node server.js /app/server.js
USER node
EXPOSE 8080
CMD ["node", "/app/server.js"]
ANTRIEB_CONTAINER_EOF
cat > /home/nodeapp/.config/containers/systemd/node-hello.container <<'ANTRIEB_QUADLET_EOF'
[Unit]
Description=Node.js hello-world rootless container
Wants=network-online.target
After=network-online.target

[Container]
Image=localhost/node-hello:latest
ContainerName=node-hello
PublishPort=0.0.0.0:8080:8080

[Service]
Restart=always
RestartSec=5
TimeoutStartSec=300

[Install]
WantedBy=default.target
ANTRIEB_QUADLET_EOF
chown -R nodeapp:nodeapp /home/nodeapp/app /home/nodeapp/.config
chmod 0644 /home/nodeapp/app/server.js /home/nodeapp/app/Containerfile /home/nodeapp/.config/containers/systemd/node-hello.container
printf 'created=%s\n' /home/nodeapp/.config/containers/systemd/node-hello.container

